class ConnectionDetails:
    def __init__(self, host, port, username, password, secure=False, login_disabled=False, timeout=None, use_m2m=False,
                 alias="default", read_only=False, update_expired_password=True):
        """
        Initialize connection details for vDU API.

        :param str host: hostname or IP address of the vDU API host
        :param str port: port on which vDU API is exposed
        :param str username: username used in authorization credentials
        :param str password: password used in authorization credentials
        :param bool secure: use HTTPS for the connection, defaults to False
        :param bool login_disabled: if True, login request will not be sent, defaults to False
        :param Union[int, float, None] timeout: timeout for the API login request, defaults to None
        :param bool use_m2m: use M2M interface to send login, defaults to False
        :param str alias: connection alias, defaults to 'default'
        :param bool read_only: if True, the connection will be in read-only mode, defaults to False
        :param bool update_expired_password: if True, expired password will be updated, defaults to True
        """
        self.protocol = 'https://' if secure else 'http://'
        self.host = host
        self.port = port
        self.secure = secure
        self.username = username
        self.password = password
        self.login_disabled = login_disabled
        self.timeout = int(timeout) if timeout else None
        self.use_m2m = use_m2m
        self.access_token = None
        self.alias = f"{alias}_{id(self)}"
        self.read_only = read_only
        self.update_expired_password = update_expired_password
        self.base_url = f"{self.protocol}{ConnectionDetails.format_host_for_base_url(self.host)}:{self.port}"

    @staticmethod
    def format_host_for_base_url(host):
        """
        Format the host for the base URL, ensuring IPv6 addresses are enclosed in brackets.
        If the host is not a valid IPv6 address, it will be returned as is.

        :param host: Hostname or IP address to format.

        :return: Formatted host string suitable for base URL.
        :rtype: str
        """
        host = host.rstrip("]").lstrip("[")
        try:
            if isinstance(ip_address(u(str(host))), IPv6Address):
                return f'[{host}]'
            else:
                return host
        except (ValueError, TypeError):
            return host

    def get_api_client_configuration(self, original_endpoint):
        """
        Get the API client configuration based on the original endpoint.
        This method modifies the original endpoint to match the base URL of the connection details.
        It removes the protocol and localhost part from the original endpoint and appends it to the base URL.

        :param original_endpoint: the original endpoint URL to be modified.

        :returns: the modified endpoint URL that matches the base URL of the connection details.
        :rtype: str
        """
        endpoint_match = re.match(r'^http.*localhost', original_endpoint)
        endpoint = original_endpoint.replace(endpoint_match.group(), '')
        return f'{self.base_url}{endpoint}'


class vDuProvider:

    DEFAULT = 'cuoam_26r2'

    _supported_vdus = {
        'cuoam_19b': vDuOAM19B,
        'cuoam_21b': vDuOAM21B,
        'cuoam_22r2': vDuOAM22R2,
        'cuoam_22r4': vDuOAM22R4,
        'cuoam_23r1': vDuOAM23R1,
        'cuoam_23r2': vDuOAM23R2,
        'cuoam_23r3': vDuOAM23R3,
        'cuoam_23r4': vDuOAM23R4,
        'cuoam_24r1': vDuOAM24R1,
        'cuoam_24r2': vDuOAM24R2,
        'cuoam_24r3': vDuOAM24R3,
        'cuoam_25r1': vDuOAM25R1,
        'cuoam_25r2': vDuOAM25R2,
        'cuoam_25r3': vDuOAM25R3,
        'cuoam_26r1': vDUOAM26R1,
        'cuoam_26r2': vDUOAM26R2,
    }

    @classmethod
    def create_vdu(cls, host, port, username, password, vdu_version='cuoam_26r2', secure=False, login_disabled=False,
                   need_all_info=False, timeout=None, use_m2m=False, alias='default', read_only=False,
                   update_expired_password=True):
        """
        Get a specific release-based implementation of vDU API.

        :param host: hostname of the vDU API host
        :param port: port on which vDU API is exposed
        :param username: username used in authorization credentials
        :param password: password used in authorization credentials
        :param vdu_version: API version to use, defaults to the most recent release
        :param secure: use HTTPS
        :param login_disabled: if True, login request will not be sent, defaults to False
        :param boolean need_all_info: is full login response info needed. defaults to False
        :param timeout: timeout for the API requests, defaults to None
        :param use_m2m: use M2M interface to send login, defaults to False
        :param alias: connection alias, defaults to 'default'
        :param read_only: if True, the connection will be in read-only mode, defaults to False
        :param update_expired_password: if True, expired password will be updated, defaults to True

        :raises: vDuVersionNotSupported: if the provided vdu_version is not supported

        :returns: a specific release-based implementation of vDU API.
        """
        if vdu_version in vDuProvider._supported_vdus:

            if vdu_version != vDuProvider.DEFAULT:
                log_warning(f"You are using vdu_version={vdu_version}, which is different from the latest version - "
                            f"{vDuProvider.DEFAULT}. Please bear in mind that in order to have access to the latest library "
                            f"updates the default value of vdu_version should be used.")

            con_details = ConnectionDetails(host=host,
                                            port=port,
                                            username=username,
                                            password=password,
                                            secure=secure,
                                            login_disabled=login_disabled,
                                            timeout=timeout,
                                            use_m2m=use_m2m,
                                            alias=alias,
                                            read_only=read_only,
                                            update_expired_password=update_expired_password)

            return vDuProvider._supported_vdus[vdu_version](con_details=con_details, need_all_info=need_all_info)

        raise vDuVersionNotSupported(vdu_version)

    @classmethod
    def get_all_supported_versions(cls):
        """
        Get all supported vDU API versions.

        :returns: a list of supported vDU API versions.
        """
        return vDuProvider._supported_vdus.keys()
